import{_ as o,o as t,c as r,a0 as s}from"./chunks/framework.B6reNh8h.js";const h=JSON.parse('{"title":"Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundaries.md","filePath":"explanation/boundaries.md"}'),a={name:"explanation/boundaries.md"};function i(n,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h1><p>Pavo owns <strong>visualization hosting</strong> — driver discovery, ViewNode interpretation, contribution-slot merge, renderer-plugin dispatch, and the three renderers (CLI, TUI, web). Neighbors own theirs:</p><ul><li><strong>tamias</strong> — distribution. Drivers are tamias content packages: executables named <code>tamias-driver-&lt;type&gt;</code> found on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code>. Pavo never re-implements transport or content types; it only <em>executes</em> what tamias installed.</li><li><strong>products</strong> (myco, kuda, sturn, mimus, cuora, …) — state owners. They ship drivers that proxy their existing <code>serve</code> wires (see the <a href="/pavo/how-to/write-a-driver.html#the-proxy-pattern-recommended-for-real-products">proxy pattern</a>). Rust drivers are typically authored with <code>pavo-driver-kit</code> — an in-repo convenience SDK, not a second contract: it wraps <code>pavo-protocol</code> types and the ndjson loop, and anything it doesn&#39;t cover is written against the protocol directly. Pavo never reads product internals — no myco files, no kuda sqlite, no store schemas. If a driver needs product state, the product&#39;s own <code>serve</code> is the API.</li><li><strong>cuora</strong> — secrets. Driver credentials via <code>cuora://</code> refs; pavo never sees values.</li><li><strong>rampho</strong> — the <code>SceneNode → ViewNode</code> precedent: media render pipelines are rampho&#39;s, UI trees are pavo&#39;s.</li><li><strong>peregrin</strong> — orchestration. Multi-actor concerns (who may view what, from where) are policy; pavo serves one localhost user. Note: peregrin&#39;s <code>tamias-driver-peregrin</code> is a tamias <em>content</em> driver for bundle install/deploy — it does not yet serve pavo views.</li><li><strong>sepia</strong> — session lifecycle; unrelated to rendering.</li></ul><h2 id="what-pavo-deliberately-doesn-t-do" tabindex="-1">What pavo deliberately doesn&#39;t do <a class="header-anchor" href="#what-pavo-deliberately-doesn-t-do" aria-label="Permalink to &quot;What pavo deliberately doesn&#39;t do&quot;">​</a></h2><ul><li><strong>No plugin system beyond drivers.</strong> &quot;Files, not frameworks&quot; — a driver is an executable on <code>PATH</code>; renderer plugins are the same mechanism with a <code>renderers[]</code> manifest claim.</li><li><strong>No product semantics.</strong> ViewNode kinds are generic (<code>table</code>, not <code>issue-list</code>); meaning lives in the driver&#39;s queries and labels. The config API is namespaced dotted keys, never file paths.</li><li><strong>No host-side writes.</strong> <code>form</code> nodes submit through the driver&#39;s own <code>submit</code> wire op — pavo hosts collect field values and display the <code>SubmitResult</code>, but every mutation semantic (what <code>submit_op</code> means, what gets written) belongs to the driver. Drivers stay proxies; pavo never touches product state.</li><li><strong>No daemon.</strong> <code>pavo serve</code> is a per-user localhost bridge bound to <code>127.0.0.1</code>, not a service. Multi-user or remote hosting would be a different tool.</li><li><strong>No HTML from drivers.</strong> The IR is declarative; <code>svg</code> is the only self-contained markup a plugin may emit. Anything richer is <code>placeholder</code>/<code>embed</code> resolved host-side.</li></ul>',5)])])}const m=o(a,[["render",i]]);export{h as __pageData,m as default};
